  [27638] = { "対象を引き裂いて$N1のダメージを与え、さらに$D1かけて$N2のダメージを与えます。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0xd23334a8, 0x59c933ab, "uu" },
  [27640] = { "敵にShadowダメージを与え、$D1の間、移動速度を低下させます。", "$D1かけてShadowダメージを受けます。\n移動速度が低下しています。", 0xb24a12b1, 0x0ff93482, "uu" },
  [27641] = { "敵を恐怖に陥れ、$D1の間、恐怖で逃げ回らせます。一度に恐怖状態にできる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x790d3c30, 0xfa67e4a8, "uu" },
