  [27753] = { "最初に近づいた敵を凍らせ、最大$D1の間、一切の行動をできなくする冷気の罠を設置します。ダメージを受けると氷は砕けます。罠は$D2の間残ります。罠は戦闘中でないときにしか設置できません。同時に有効にできる罠は一つだけです。", nil, 0x0d5b0458, nil, "um" },
