  [27760] = { "敵を羊に変え、最大$D1の間さまよわせます。さまよっている間、羊は攻撃も呪文の詠唱もできませんが、非常に速く回復します。ダメージを受けると元の姿に戻ります。一度にポリモーフできる対象は1体だけです。獣、ドラゴン、巨人、人型生物、小動物にのみ有効です。", "攻撃も呪文の詠唱もできません。\n体力の回復量が増加しています。", 0x1f2ac94a, 0x4096b919, "uu" },
  [27766] = { "前方$N1ヤード以内の最も近いtonkに砲弾を撃ち込みます。$N2のダメージを与えます。", nil, 0x581acb4e, nil, "um" },
