  [27797] = { "Riptideのマナコストを$N1%軽減します。", nil, 0xd76475b7, nil, "um" },
  [27799] = { "術者の周囲で聖なる光を炸裂させ、$N2ヤード以内のすべての敵対象に$N1のHolyダメージを与え、$N3ヤード以内のパーティメンバー全員を$N4回復します。これらの効果は脅威を発生させません。\n\nHoly Fireがダメージを与えるたびに、$N5%の確率で次のHoly Novaのマナコストがなくなります。", nil, 0xa74b049b, nil, "um" },
  [27800] = { "術者の周囲で聖なる光を炸裂させ、$N2ヤード以内のすべての敵対象に$N1のHolyダメージを与え、$N3ヤード以内のパーティメンバー全員を$N4回復します。これらの効果は脅威を発生させません。\n\nHoly Fireがダメージを与えるたびに、$N5%の確率で次のHoly Novaのマナコストがなくなります。", nil, 0xa0ca80a3, nil, "um" },
  [27801] = { "術者の周囲で聖なる光を炸裂させ、$N2ヤード以内のすべての敵対象に$N1のHolyダメージを与え、$N3ヤード以内のパーティメンバー全員を$N4回復します。これらの効果は脅威を発生させません。\n\nHoly Fireがダメージを与えるたびに、$N5%の確率で次のHoly Novaのマナコストがなくなります。", nil, 0x9a49fcab, nil, "um" },
  [27806] = { "敵に毒を吐きかけ、Natureダメージを与えます。", nil, 0xe5127eab, nil, "um" },
  [27807] = { "術者の前方の円錐範囲内の敵に$N1のNatureダメージを与え、さらに$D1ごとに$N2のダメージを与えます。Nature耐性が$N4低下します。効果時間は$D2です。", "$D1ごとに$N1のNatureダメージを受けます。\nNature耐性が$N3低下します。", 0xf7dd67d4, 0xdb653789, "uu" },
  [27808] = { nil, "スタンしています。\n継続的にFrostダメージを受けます。", nil, 0x70766216, "mu" },
  [27811] = { "近接または遠隔のクリティカルヒットを受けるか、一度の攻撃で最大体力の$N1%を超えるダメージを受けると、受けたダメージの$N2%を$D1かけて回復します。この効果を更新すると、残りの回復量は引き継がれます。", nil, 0xd68858e4, nil, "um" },
  [27813] = { "$D1かけて対象を回復します。", "最近受けたクリティカルヒットのダメージを$D1かけて回復しています。", 0x826cb432, 0x22177e06, "uu" },
  [27814] = { "敵を蹴りつけて$N1のダメージを与え、$D1の間、詠唱中の呪文を妨害します。", "Silenced", 0x58ded920, 0xeea90c8c, "uu" },
  [27819] = { nil, "マナが不安定になっています！", nil, 0x7d5c999c, "mu" },
  [27825] = { "鋼の旋風となって、$N2ヤード以内の最大$N1体の敵を攻撃し、それぞれに武器ダメージを与えます。", "Unrelenting Ridersがあなたを狙ってShadowboltを放つようになります。", 0x019c0e2f, 0x93021ee2, "uu" },
