  [27827] = { nil, "誰にも想像できないほどの力を得ました。", nil, 0x393ecc0c, "mu" },
  [27828] = { "詠唱中にダメージを受けても、詠唱時間が延びなくなります。効果時間は$D1です。", "ダメージを受けても詠唱時間が失われず、自分に対するInterrupt効果の命中率が$N1%低下します。", 0xbd0b2d08, 0xc1cefa6c, "uu" },
