  [27990] = { "敵を恐怖に陥れ、$D1の間、恐怖で逃げ回らせます。一度に恐怖状態にできる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x790d3c30, 0xfa67e4a8, "uu" },
  [27991] = { "敵のアーマーを削り、Sunder Armorごとに$N1下げます。最大5回まで重ねられます。効果時間は$D1です。", "アーマーが低下しています。", 0xb4e55d0c, 0xc3d1fc4c, "uu" },
